import time
import hmac

def check_token(submitted_value, identity, records):
    if not isinstance(submitted_value, str) or not submitted_value:
        return False

    record = records.get(identity)

    if not record:
        return False

    stored_value = record.get('token')
    expiry_ts = record.get('expires_at')

    if stored_value is None or expiry_ts is None:
        return False

    token_match = isinstance(stored_value, str) and hmac.compare_digest(submitted_value, stored_value)

    if token_match and time.time() < expiry_ts:
        return True

    return False
